DECLARE @ID_af9b61155d8e UNIQUEIDENTIFIER,
@Name_af9b61155d8e NVARCHAR(255),
@CategoryID_af9b61155d8e UNIQUEIDENTIFIER,
@UserQuestion_af9b61155d8e NVARCHAR(MAX),
@Description_af9b61155d8e NVARCHAR(MAX),
@SQL_af9b61155d8e NVARCHAR(MAX),
@TechnicalDescription_af9b61155d8e NVARCHAR(MAX),
@OriginalSQL_af9b61155d8e NVARCHAR(MAX),
@Feedback_af9b61155d8e NVARCHAR(MAX),
@Status_af9b61155d8e NVARCHAR(15),
@QualityRank_af9b61155d8e INT,
@ExecutionCostRank_af9b61155d8e INT,
@UsesTemplate_af9b61155d8e BIT,
@AuditQueryRuns_af9b61155d8e BIT,
@CacheEnabled_af9b61155d8e BIT,
@CacheTTLMinutes_af9b61155d8e INT,
@CacheMaxSize_af9b61155d8e INT,
@EmbeddingVector_af9b61155d8e NVARCHAR(MAX),
@EmbeddingModelID_af9b61155d8e UNIQUEIDENTIFIER,
@CacheValidationSQL_af9b61155d8e NVARCHAR(MAX),
@SQLDialectID_af9b61155d8e UNIQUEIDENTIFIER,
@Reusable_af9b61155d8e BIT,
@ExternalDataSourceID_af9b61155d8e UNIQUEIDENTIFIER,
@IsMaterialized_af9b61155d8e BIT,
@Configuration_af9b61155d8e NVARCHAR(MAX)
SET
  @ID_af9b61155d8e = '4513AE64-76A5-432C-BA67-360C8A97753F'
SET
  @Name_af9b61155d8e = N'RubricDriftPeriodMeans'
SET
  @CategoryID_af9b61155d8e = '5609FBC7-381C-4F9C-9C74-04B52C1FF3DA'
SET
  @UserQuestion_af9b61155d8e = N'How did each agent''s rubric criterion mean change between the last two periods?'
SET
  @Description_af9b61155d8e = N'Mean normalized score per agent, rubric, and criterion for two time windows. Counts only Submitted evaluations that are not self-checks, and only the evaluator''s own scores.'
SET
  @SQL_af9b61155d8e = N'-- Per-agent, per-rubric, per-criterion means for the two drift windows.
-- Submitted evaluations only. Self-checks are left out. Group rollups are left out.
-- The client renders AgentName, RubricName, and CriterionKey. It does not read raw score rows.
SELECT
    agent.[Name] AS AgentName,
    rubric.[Name] AS RubricName,
    criterion.[Key] AS CriterionKey,
    AVG(CASE
        WHEN evaluation.[SubmittedAt] >= {{ currentStart | sqlDate }}
         AND evaluation.[SubmittedAt] < {{ periodEnd | sqlDate }}
        THEN score.[NormalizedScore]
    END) AS CurrentMean,
    AVG(CASE
        WHEN evaluation.[SubmittedAt] >= {{ previousStart | sqlDate }}
         AND evaluation.[SubmittedAt] < {{ currentStart | sqlDate }}
        THEN score.[NormalizedScore]
    END) AS PreviousMean
FROM [${flyway:defaultSchema}].[RubricEvaluationScore] score
INNER JOIN [${flyway:defaultSchema}].[RubricEvaluation] evaluation ON evaluation.[ID] = score.[EvaluationID]
INNER JOIN [${flyway:defaultSchema}].[RubricVersion] version ON version.[ID] = evaluation.[RubricVersionID]
INNER JOIN [${flyway:defaultSchema}].[Rubric] rubric ON rubric.[ID] = version.[RubricID]
INNER JOIN [${flyway:defaultSchema}].[RubricCriterion] criterion ON criterion.[ID] = score.[CriterionID]
INNER JOIN [${flyway:defaultSchema}].[AIAgentRun] run ON run.[ID] = TRY_CONVERT(uniqueidentifier, evaluation.[SubjectRecordID])
INNER JOIN [${flyway:defaultSchema}].[AIAgent] agent ON agent.[ID] = run.[AgentID]
WHERE evaluation.[Status] = ''Submitted''
  AND evaluation.[EvaluatorType] <> ''Self''
  AND score.[IsComputed] = 0
  AND score.[NormalizedScore] IS NOT NULL
  AND evaluation.[SubmittedAt] >= {{ previousStart | sqlDate }}
  AND evaluation.[SubmittedAt] < {{ periodEnd | sqlDate }}
GROUP BY agent.[Name], rubric.[Name], criterion.[Key]
'
SET
  @TechnicalDescription_af9b61155d8e = N'Groups RubricEvaluationScore by AI Agent name, Rubric name, and criterion Key. previousStart, currentStart, and periodEnd ({{ previousStart | sqlDate }}, {{ currentStart | sqlDate }}, {{ periodEnd | sqlDate }}) bound the two windows [previousStart, currentStart) and [currentStart, periodEnd). Status is Submitted and EvaluatorType is not Self.'
SET
  @Status_af9b61155d8e = N'Approved'
SET
  @QualityRank_af9b61155d8e = 8
SET
  @ExecutionCostRank_af9b61155d8e = 3
SET
  @UsesTemplate_af9b61155d8e = 1
SET
  @AuditQueryRuns_af9b61155d8e = 0
SET
  @CacheEnabled_af9b61155d8e = 0
SET
