SET
  @Status_a6cbcacb543c = N'Active'
SET
  @CodeLocked_a6cbcacb543c = 0
SET
  @ID_a6cbcacb543c = '9A3CAF75-D794-4223-9AEE-A40AE8A0A012' EXEC [${flyway:defaultSchema}].spUpdateRemoteOperation @Name = @Name_a6cbcacb543c,
  @OperationKey = @OperationKey_a6cbcacb543c,
  @CategoryID = @CategoryID_a6cbcacb543c,
  @Description = @Description_a6cbcacb543c,
  @InputTypeName = @InputTypeName_a6cbcacb543c,
  @InputTypeDefinition = @InputTypeDefinition_a6cbcacb543c,
  @InputTypeIsArray = @InputTypeIsArray_a6cbcacb543c,
  @OutputTypeName = @OutputTypeName_a6cbcacb543c,
