  @RequiresSystemUser = @RequiresSystemUser_a6cbcacb543c,
  @GenerationType = @GenerationType_a6cbcacb543c,
  @Code = @Code_a6cbcacb543c,
  @Code_Clear = 1,
  @CodeApprovalStatus = @CodeApprovalStatus_a6cbcacb543c,
  @CodeApprovedByUserID = @CodeApprovedByUserID_a6cbcacb543c,
