  @Name_ed610355e660 = N'Draft Workflow'
SET
  @OperationKey_ed610355e660 = N'Workflow.Draft'
SET
  @CategoryID_ed610355e660 = '0A7E9FD9-45BD-4ECF-ABD2-0EFF73C879E6'
SET
  @Description_ed610355e660 = N'Draft a workflow''s steps from a plain-English description. Returns a TaskGraphSpec and persists NOTHING — the draft goes to the canvas for the author to review, and only Workflow.Save commits it, which is what makes the front door''s "nothing is saved until you approve it" promise true rather than merely stated. Constrained to agents that actually exist on the instance, because a workflow referencing an unknown agent cannot be saved and a draft that cannot be saved wastes the author''s time. Validated with the SAME ValidateTaskGraphSpec the canvas and Workflow.Save run, so a draft that comes back cannot be rejected later for a reason drafting never checked. Implemented by WorkflowDraftServerOperation in @memberjunction/task-graph.'
SET
  @InputTypeName_ed610355e660 = N'WorkflowDraftInput'
SET
  @InputTypeDefinition_ed610355e660 = N'/** Input for `Workflow.Draft`. */
export interface WorkflowDraftInput {
    /** What the person wants done, in their own words. */
    description: string;
    /** What to call the workflow. Carried through to the draft''s `workflowName`. */
    workflowName: string;
}'
SET
  @InputTypeIsArray_ed610355e660 = 0
SET
  @OutputTypeName_ed610355e660 = N'WorkflowDraftOutput'
SET
  @OutputTypeDefinition_ed610355e660 = N'/** Output of `Workflow.Draft`. */
export interface WorkflowDraftOutput {
    /** True when a structurally valid draft came back. */
    success: boolean;
    /**
     * The drafted graph, in the same `TaskGraphSpec` shape the canvas and `Workflow.Save` use.
     *
     * A DRAFT — nothing is persisted. The author reviews it on the canvas and commits with
     * `Workflow.Save`, which is what makes "nothing is saved until you approve it" true rather than
     * merely promised.
     */
    graph?: {
        workflowName: string;
        reasoning?: string;
        tasks: Array<{
            /** One step. `kind` selects which `configuration` shape applies. */
            tempId: string;
            name: string;
            description: string;
            kind: ''Agent'' | ''Action'' | ''Human'' | ''Prompt'' | ''ForEach'' | ''While'' | ''External'' | ''Decision'';
            configuration:
                | { agentName: string; message?: string; templateParameters?: Record<string, string> }
                | { actionName: string; inputMapping?: string; outputMapping?: string }
                | { assignToUserID?: string; instructions?: string }
                | { promptName: string; templateParameters?: Record<string, string> }
                | { collectionPath: string; itemVariable?: string; maxIterations?: number; executionMode?: ''sequential'' | ''parallel'' }
                | { condition: string; itemVariable?: string; maxIterations?: number }
                | { domain: string; ref?: string } | { promptName?: string; state?: string; questions: Record<string, { kind: ''Likelihood''; instructions: string; minConfidence?: number } | { kind: ''Choice''; instructions: string; options: Array<{ value: string; description: string }>; minConfidence?: number } | { kind: ''Score''; instructions: string; levels: string[]; minConfidence?: number }> };
            dependsOn: Array<string | { tempId: string; condition?: string; dependencyType?: ''Prerequisite'' | ''Corequisite'' | ''Optional''; priority?: number; sequence?: number; exclusiveGroup?: string; pathPoints?: string }>;
            policy?: { timeoutSeconds?: number; retryCount?: number; onError?: ''fail'' | ''continue'' };
            /** Canvas geometry. Presentation only: the dispatcher ignores it, the validator never requires it. */
            layout?: { x?: number; y?: number; width?: number; height?: number };
            inputPayload?: Record<string, unknown>;
        }>;
        continuation?: ''message'' | ''reinvoke'' | ''none'';
        durable?: boolean;
        /** ''edges'' (flow-compiled) evaluates a failed step''s outgoing edges; ''block'' (default) is terminal for dependents. */
        failureSemantics?: ''block'' | ''edges'';
    };
    /** Why drafting failed, or why the model''s output was rejected. */
    errorMessage?: string;
}'
